import itertools
def is_valid_schedule(schedule):
    for w in range(6):
        groups = [[] for _ in range(8)]
        for p in range(32):
            g = schedule[w*32 + p]
            if not (0 <= g <= 7):
                return False
            groups[g].append(p)
        for g in range(8):
            if len(groups[g]) != 4:
                return False
    pair_week = {}
    for w in range(6):
        for g in range(8):
            group = [p for p in range(32) if schedule[w*32 + p] == g]
            for pair in itertools.combinations(group, 2):
                pair_tuple = tuple(sorted(pair))
                if pair_tuple in pair_week:
                    return False
                pair_week[pair_tuple] = w
    return True
